#define THREADS 256

template <typename scalar_t>
__global__ void
radius_kernel(const scalar_t *__restrict__ x, const scalar_t *__restrict__ y,
              const int64_t *__restrict__ ptr_x,
              const int64_t *__restrict__ ptr_y, int64_t *__restrict__ row,
              int64_t *__restrict__ col, const scalar_t r, const int64_t n,
              const int64_t m, const int64_t dim, const int64_t num_examples,
              const int64_t max_num_neighbors,
              const bool ignore_same_index) {

  const int64_t n_y = blockIdx.x * blockDim.x + threadIdx.x;
  if (n_y >= m)
    return;

  int64_t count = 0;
  const int64_t example_idx = get_example_idx(n_y, ptr_y, num_examples);

  for (int64_t n_x = ptr_x[example_idx]; n_x < ptr_x[example_idx + 1]; n_x++) {
    scalar_t dist = 0;
    for (int64_t d = 0; d < dim; d++) {
      dist += (x[n_x * dim + d] - y[n_y * dim + d]) *
              (x[n_x * dim + d] - y[n_y * dim + d]);
    }

    if (dist < r && !(ignore_same_index && n_y == n_x)) {
      row[n_y * max_num_neighbors + count] = n_y;
      col[n_y * max_num_neighbors + count] = n_x;
      count++;
    }

    if (count >= max_num_neighbors)
      break;
  }
}

torch::Tensor radius_cuda(const torch::Tensor x, const torch::Tensor y,
                          std::optional<torch::Tensor> ptr_x,
                          std::optional<torch::Tensor> ptr_y, const double r,
                          const int64_t max_num_neighbors,
                          const bool ignore_same_index) {
  CHECK_CUDA(x);
  CHECK_CONTIGUOUS(x);
  CHECK_INPUT(x.dim() == 2);
  CHECK_CUDA(y);
  CHECK_CONTIGUOUS(y);
  CHECK_INPUT(y.dim() == 2);
  CHECK_INPUT(x.size(1) == y.size(1));

  c10::cuda::MaybeSetDevice(x.get_device());

  if (ptr_x.has_value()) {
    CHECK_CUDA(ptr_x.value());
    CHECK_INPUT(ptr_x.value().dim() == 1);
  } else
    ptr_x = torch::arange(0, x.size(0) + 1, x.size(0),
                          x.options().dtype(torch::kLong));

  if (ptr_y.has_value()) {
    CHECK_CUDA(ptr_y.value());
    CHECK_INPUT(ptr_y.value().dim() == 1);
  } else
    ptr_y = torch::arange(0, y.size(0) + 1, y.size(0),
                          y.options().dtype(torch::kLong));

  CHECK_INPUT(ptr_x.value().numel() == ptr_y.value().numel());

  auto row =
      torch::full(y.size(0) * max_num_neighbors, -1, ptr_y.value().options());
  auto col =
      torch::full(y.size(0) * max_num_neighbors, -1, ptr_y.value().options());

  dim3 BLOCKS((y.size(0) + THREADS - 1) / THREADS);

  auto stream = at::cuda::getCurrentCUDAStream();
  auto scalar_type = x.scalar_type();
  AT_DISPATCH_FLOATING_TYPES_AND2(
      at::ScalarType::Half, at::ScalarType::BFloat16, scalar_type, "_", [&] {
        radius_kernel<scalar_t><<<BLOCKS, THREADS, 0, stream>>>(
            x.data_ptr<scalar_t>(), y.data_ptr<scalar_t>(),
            ptr_x.value().data_ptr<int64_t>(),
            ptr_y.value().data_ptr<int64_t>(), row.data_ptr<int64_t>(),
            col.data_ptr<int64_t>(), r * r, x.size(0), y.size(0), x.size(1),
            ptr_x.value().numel() - 1, max_num_neighbors, ignore_same_index);
      });

  auto mask = row != -1;
  return torch::stack({row.masked_select(mask), col.masked_select(mask)}, 0);
}

#pragma once

#include <limits>
#include <map>

#include "atomics.cuh"

enum ReductionType { SUM, MEAN, MUL, DIV, MIN, MAX };

const std::map<std::string, ReductionType> reduce2REDUCE = {
    {"sum", SUM}, {"mean", MEAN}, {"mul", MUL},
    {"div", DIV}, {"min", MIN},   {"max", MAX},
};

#define AT_DISPATCH_REDUCTION_TYPES(reduce, ...)                               \
  [&] {                                                                        \
    switch (reduce2REDUCE.at(reduce)) {                                        \
    case SUM: {                                                                \
      static constexpr ReductionType REDUCE = SUM;                                        \
      return __VA_ARGS__();                                                    \
    }                                                                          \
    case MEAN: {                                                               \
      static constexpr ReductionType REDUCE = MEAN;                                       \
      return __VA_ARGS__();                                                    \
    }                                                                          \
    case MUL: {                                                                \
      static constexpr ReductionType REDUCE = MUL;                                        \
      return __VA_ARGS__();                                                    \
    }                                                                          \
    case DIV: {                                                                \
      static constexpr ReductionType REDUCE = DIV;                                        \
      return __VA_ARGS__();                                                    \
    }                                                                          \
    case MIN: {                                                                \
      static constexpr ReductionType REDUCE = MIN;                                        \
      return __VA_ARGS__();                                                    \
    }                                                                          \
    case MAX: {                                                                \
      static constexpr ReductionType REDUCE = MAX;                                        \
      return __VA_ARGS__();                                                    \
    }                                                                          \
    }                                                                          \
  }()

template <typename scalar_t, ReductionType REDUCE> struct Reducer {
  static inline __host__ __device__ scalar_t init() {
    if (REDUCE == MUL || REDUCE == DIV)
      return (scalar_t)1;
    else if (REDUCE == MIN)
      return std::numeric_limits<scalar_t>::max();
    else if (REDUCE == MAX)
      return std::numeric_limits<scalar_t>::lowest();
    else
      return (scalar_t)0;
  }

  static inline __host__ __device__ void update(scalar_t *val,
                                                scalar_t new_val) {
    if (REDUCE == SUM || REDUCE == MEAN)
      *val = *val + new_val;
    else if (REDUCE == MUL)
      *val = *val * new_val;
    else if (REDUCE == DIV)
      *val = *val / new_val;
    else if ((REDUCE == MIN && new_val < *val) ||
             (REDUCE == MAX && new_val > *val)) {
      *val = new_val;
    }
  }

  static inline __host__ __device__ void update(scalar_t *val, scalar_t new_val,
                                                int64_t *arg, int64_t new_arg) {
    if (REDUCE == SUM || REDUCE == MEAN)
      *val = *val + new_val;
    else if (REDUCE == MUL)
      *val = *val * new_val;
    else if (REDUCE == DIV)
      *val = *val / new_val;
    else if ((REDUCE == MIN && new_val < *val) ||
             (REDUCE == MAX && new_val > *val)) {
      *val = new_val;
      *arg = new_arg;
    }
  }

  static inline __host__ __device__ void write(scalar_t *address, scalar_t val,
                                               int64_t *arg_address,
                                               int64_t arg, int count) {
    if (REDUCE == SUM || REDUCE == MUL || REDUCE == DIV)
      *address = val;
    else if (REDUCE == MEAN)
      *address = val / (scalar_t)(count > 0 ? count : 1);
    else if (REDUCE == MIN || REDUCE == MAX) {
      if (count > 0) {
        *address = val;
        *arg_address = arg;
      } else
        *address = (scalar_t)0;
    }
  }

  static inline __device__ void atomic_write(scalar_t *address, scalar_t val) {
    if (REDUCE == SUM || REDUCE == MEAN)
      atomAdd(address, val);
    else if (REDUCE == MUL)
      atomMul(address, val);
    else if (REDUCE == DIV)
      atomDiv(address, val);
    else if (REDUCE == MIN)
      atomMin(address, val);
    else if (REDUCE == MAX)
      atomMax(address, val);
  }
};
#include "scatter_cuda.h"

#include <ATen/cuda/CUDAContext.h>
#include <ATen/cuda/detail/IndexUtils.cuh>
#include <ATen/cuda/detail/TensorInfo.cuh>

#include "reducer.cuh"
#include "utils.cuh"

#define THREADS 256
#define BLOCKS(N) (N + THREADS - 1) / THREADS

template <typename scalar_t, ReductionType REDUCE>
__global__ void
scatter_kernel(const scalar_t *src_data,
               const at::cuda::detail::TensorInfo<int64_t, int> index_info,
               scalar_t *out_data, int E, int K, int N, int numel) {

  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;

  int b = thread_idx / (E * K);
  int k = thread_idx % K;

  if (thread_idx < numel) {
    int offset = at::cuda::detail::IndexToOffset<int64_t, int, -1>::get(
        thread_idx, index_info);
    int64_t idx = index_info.data[offset];

    Reducer<scalar_t, REDUCE>::atomic_write(out_data + b * N * K + idx * K + k,
                                            src_data[thread_idx]);
  }
}

template <typename scalar_t>
__global__ void
scatter_arg_kernel(const scalar_t *src_data,
                   const at::cuda::detail::TensorInfo<int64_t, int> index_info,
                   const scalar_t *out_data, int64_t *arg_out_data, int E,
                   int K, int N, int numel) {

  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;

  int b = thread_idx / (E * K);
  int e = (thread_idx / K) % E;
  int k = thread_idx % K;

  if (thread_idx < numel) {
    int offset = at::cuda::detail::IndexToOffset<int64_t, int, -1>::get(
        thread_idx, index_info);
    int64_t idx = index_info.data[offset];

    if (src_data[thread_idx] == out_data[b * N * K + idx * K + k]) {
      arg_out_data[b * N * K + idx * K + k] = e;
    }
  }
}

std::tuple<torch::Tensor, std::optional<torch::Tensor>>
scatter_cuda(torch::Tensor src, torch::Tensor index, int64_t dim,
             std::optional<torch::Tensor> optional_out,
             std::optional<int64_t> dim_size, std::string reduce) {
  CHECK_CUDA(src);
  CHECK_CUDA(index);
  if (optional_out.has_value())
    CHECK_CUDA(optional_out.value());
  c10::cuda::MaybeSetDevice(src.get_device());

  CHECK_INPUT(src.dim() == index.dim());
  for (auto i = 0; i < index.dim() - 1; i++)
    CHECK_INPUT(src.size(i) >= index.size(i));

  src = src.contiguous();

  torch::Tensor out;
  if (optional_out.has_value()) {
    out = optional_out.value().contiguous();
    for (auto i = 0; i < out.dim(); i++)
      if (i != dim)
        CHECK_INPUT(src.size(i) == out.size(i));
  } else {
    auto sizes = src.sizes().vec();
    if (dim_size.has_value())
      sizes[dim] = dim_size.value();
    else if (index.numel() == 0)
      sizes[dim] = 0;
    else {
      sizes[dim] = 1 + index.max().cpu().data_ptr<int64_t>()[0];
    }
    out = torch::empty(sizes, src.options());
  }

  std::optional<torch::Tensor> arg_out = std::nullopt;
  int64_t *arg_out_data = nullptr;
  if (reduce2REDUCE.at(reduce) == MIN || reduce2REDUCE.at(reduce) == MAX) {
    arg_out = torch::full_like(out, src.size(dim), index.options());
    arg_out_data = arg_out.value().data_ptr<int64_t>();
  }

  if (src.numel() == 0) {
    if (!optional_out.has_value())
      out.fill_(0);
    return std::make_tuple(out, arg_out);
  }

  auto B = 1;
  for (auto i = 0; i < dim; i++)
    B *= src.size(i);
  auto E = src.size(dim);
  auto K = src.numel() / (B * E);
  auto N = out.size(dim);

  auto index_info = at::cuda::detail::getTensorInfo<int64_t, int>(index);
  auto stream = at::cuda::getCurrentCUDAStream();
  AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, src.scalar_type(), "_", [&] {
    auto src_data = src.data_ptr<scalar_t>();
    auto out_data = out.data_ptr<scalar_t>();

    AT_DISPATCH_REDUCTION_TYPES(reduce, [&] {
      if (!optional_out.has_value())
        out.fill_(Reducer<scalar_t, REDUCE>::init());

      scatter_kernel<scalar_t, REDUCE>
          <<<BLOCKS(src.numel()), THREADS, 0, stream>>>(
              src_data, index_info, out_data, E, K, N, src.numel());

      if (!optional_out.has_value() && (REDUCE == MIN || REDUCE == MAX))
        out.masked_fill_(out == Reducer<scalar_t, REDUCE>::init(), (scalar_t)0);

      if (REDUCE == MIN || REDUCE == MAX)
        scatter_arg_kernel<scalar_t>
            <<<BLOCKS(src.numel()), THREADS, 0, stream>>>(
                src_data, index_info, out_data, arg_out_data, E, K, N,
                src.numel());
    });
  });

  return std::make_tuple(out, arg_out);
}

#include "segment_csr_cuda.h"

#include <ATen/cuda/CUDAContext.h>
#include <ATen/cuda/detail/IndexUtils.cuh>
#include <ATen/cuda/detail/TensorInfo.cuh>

#include "index_info.cuh"
#include "reducer.cuh"
#include "utils.cuh"

#define THREADS 256
#define BLOCKS(TB, N) (TB * N + THREADS - 1) / THREADS
#define FULL_MASK 0xffffffff

template <typename scalar_t, ReductionType REDUCE, int TB>
__global__ void
segment_csr_kernel(const scalar_t *src_data,
                   const at::cuda::detail::TensorInfo<int64_t, int> indptr_info,
                   scalar_t *out_data, int64_t *arg_out_data, size_t N,
                   size_t E) {

  // Each warp processes exactly `32/TB` rows and aggregates all row values
  // via a parallel reduction.

  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
  int row_idx = thread_idx / TB;
  int lane_idx = thread_idx & (TB - 1);

  if (row_idx < N) {
    int offset = IndexPtrToOffset<int64_t>::get(row_idx, indptr_info);
    int64_t row_start = __ldg(indptr_info.data + offset);
    int64_t row_end = __ldg(indptr_info.data + offset +
                            indptr_info.strides[indptr_info.dims - 1]);

    scalar_t val = Reducer<scalar_t, REDUCE>::init();
    int64_t arg, arg_tmp;

    offset = (row_idx / (indptr_info.sizes[indptr_info.dims - 1] - 1)) * E;
    for (int64_t src_idx = row_start + lane_idx; src_idx < row_end;
         src_idx += TB) {
      Reducer<scalar_t, REDUCE>::update(&val, src_data[offset + src_idx], &arg,
                                        src_idx);
    }

#pragma unroll
    for (int i = TB / 2; i > 0; i /= 2) {
      // Parallel reduction inside a single warp.
      if (REDUCE == MIN || REDUCE == MAX)
        arg_tmp = SHFL_DOWN_SYNC(FULL_MASK, arg, i);
      Reducer<scalar_t, REDUCE>::update(
          &val, SHFL_DOWN_SYNC(FULL_MASK, val, i), &arg, arg_tmp);
    }

    if (lane_idx == 0) {
      Reducer<scalar_t, REDUCE>::write(out_data + row_idx, val,
                                       arg_out_data + row_idx, arg,
                                       row_end - row_start);
    }
  }
}

template <typename scalar_t, ReductionType REDUCE>
__global__ void segment_csr_broadcast_kernel(
    const scalar_t *src_data,
    const at::cuda::detail::TensorInfo<int64_t, int> indptr_info,
    scalar_t *out_data, int64_t *arg_out_data, size_t N, size_t K, size_t E) {

  // Each thread processes exactly one row. It turned out that is more
  // efficient than using shared memory due to avoiding synchronization
  // barriers.

  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
  int row_idx = thread_idx / K;
  int lane_idx = thread_idx % K;

  if (thread_idx < N * K) {
    int offset = IndexPtrToOffset<int64_t>::get(row_idx, indptr_info);
    int64_t row_start = __ldg(indptr_info.data + offset);
    int64_t row_end = __ldg(indptr_info.data + offset +
                            indptr_info.strides[indptr_info.dims - 1]);

    scalar_t val = Reducer<scalar_t, REDUCE>::init();
    int64_t arg;

    offset = (row_idx / (indptr_info.sizes[indptr_info.dims - 1] - 1)) * E * K;
    for (int64_t src_idx = row_start; src_idx < row_end; src_idx++) {
      Reducer<scalar_t, REDUCE>::update(
          &val, src_data[offset + K * src_idx + lane_idx], &arg, src_idx);
    }

    Reducer<scalar_t, REDUCE>::write(out_data + thread_idx, val,
                                     arg_out_data + thread_idx, arg,
                                     row_end - row_start);
  }
}

std::tuple<torch::Tensor, std::optional<torch::Tensor>>
segment_csr_cuda(torch::Tensor src, torch::Tensor indptr,
                 std::optional<torch::Tensor> optional_out,
                 std::string reduce) {
  CHECK_CUDA(src);
  CHECK_CUDA(indptr);
  if (optional_out.has_value())
    CHECK_CUDA(optional_out.value());
  c10::cuda::MaybeSetDevice(src.get_device());

  CHECK_INPUT(src.dim() >= indptr.dim());

  auto sizes = indptr.sizes().vec();
  for (auto i = 0; i < indptr.dim() - 1; i++)
    sizes[i] = src.size(i);
  indptr = indptr.expand(sizes);

  auto dim = indptr.dim() - 1;

  src = src.contiguous();

  torch::Tensor out;
  if (optional_out.has_value()) {
    out = optional_out.value().contiguous();
    for (int i = 0; i < out.dim(); i++)
      if (i != dim)
        CHECK_INPUT(src.size(i) == out.size(i));
    CHECK_INPUT(src.numel() == 0 || out.size(dim) == indptr.size(dim) - 1);
  } else {
    sizes = src.sizes().vec();
    sizes[dim] = std::max<int64_t>(indptr.size(dim) - 1, 0);
    out = torch::empty(sizes, src.options());
  }

  std::optional<torch::Tensor> arg_out = std::nullopt;
  int64_t *arg_out_data = nullptr;
  if (reduce2REDUCE.at(reduce) == MIN || reduce2REDUCE.at(reduce) == MAX) {
    arg_out = torch::full(out.sizes(), src.size(dim), indptr.options());
    arg_out_data = arg_out.value().data_ptr<int64_t>();
  }

  if (src.numel() == 0) {
    if (!optional_out.has_value())
      out.fill_(0);
    return std::make_tuple(out, arg_out);
  }

  auto N = out.size(dim) * (indptr.numel() / indptr.size(-1));
  auto K = out.numel() / N;
  auto E = src.size(dim);

  auto indptr_info = at::cuda::detail::getTensorInfo<int64_t, int>(indptr);
  auto stream = at::cuda::getCurrentCUDAStream();
  AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, src.scalar_type(), "_", [&] {
    auto src_data = src.data_ptr<scalar_t>();
    auto out_data = out.data_ptr<scalar_t>();

    AT_DISPATCH_REDUCTION_TYPES(reduce, [&] {
      if (K == 1) {
        segment_csr_kernel<scalar_t, REDUCE, 1>
            <<<BLOCKS(32, N), THREADS, 0, stream>>>(
                src_data, indptr_info, out_data, arg_out_data, N, E);
      } else {
        segment_csr_broadcast_kernel<scalar_t, REDUCE>
            <<<BLOCKS(1, N * K), THREADS, 0, stream>>>(
                src_data, indptr_info, out_data, arg_out_data, N, K, E);
      }
    });
  });

  return std::make_tuple(out, arg_out);
}

template <typename scalar_t, int TB>
__global__ void
gather_csr_kernel(const scalar_t *src_data,
                  const at::cuda::detail::TensorInfo<int64_t, int> indptr_info,
                  scalar_t *out_data, size_t N, size_t E) {

  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
  int row_idx = thread_idx / TB;
  int lane_idx = thread_idx % TB;

  if (row_idx < N) {
    int offset = IndexPtrToOffset<int64_t>::get(row_idx, indptr_info);
    int row_start = __ldg(indptr_info.data + offset);
    int row_end = __ldg(indptr_info.data + offset +
                        indptr_info.strides[indptr_info.dims - 1]);
    scalar_t val = __ldg(src_data + row_idx);

    offset = (row_idx / (indptr_info.sizes[indptr_info.dims - 1] - 1)) * E;
    for (int out_idx = row_start + lane_idx; out_idx < row_end; out_idx += TB) {
      out_data[offset + out_idx] = val; // "Mostly" coalesced.
    }
  }
}

template <typename scalar_t>
__global__ void gather_csr_broadcast_kernel(
    const scalar_t *src_data,
    const at::cuda::detail::TensorInfo<int64_t, int> indptr_info,
    scalar_t *out_data, size_t N, size_t K, size_t E) {

  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
  int row_idx = thread_idx / K;
  int lane_idx = thread_idx % K;

  if (thread_idx < N * K) {
    int offset = IndexPtrToOffset<int64_t>::get(row_idx, indptr_info);
    int row_start = __ldg(indptr_info.data + offset);
    int row_end = __ldg(indptr_info.data + offset +
                        indptr_info.strides[indptr_info.dims - 1]);

    scalar_t val = src_data[thread_idx]; // Coalesced.

    offset = (row_idx / (indptr_info.sizes[indptr_info.dims - 1] - 1)) * E * K;
    for (int out_idx = row_start; out_idx < row_end; out_idx++) {
      out_data[offset + K * out_idx + lane_idx] = val; // "Mostly" coalesced.
    }
  }
}

torch::Tensor gather_csr_cuda(torch::Tensor src, torch::Tensor indptr,
                              std::optional<torch::Tensor> optional_out) {
  CHECK_CUDA(src);
  CHECK_CUDA(indptr);
  if (optional_out.has_value())
    CHECK_CUDA(optional_out.value());
  c10::cuda::MaybeSetDevice(src.get_device());

  CHECK_INPUT(src.dim() >= indptr.dim());

  auto sizes = indptr.sizes().vec();
  for (auto i = 0; i < indptr.dim() - 1; i++)
    sizes[i] = src.size(i);
  indptr = indptr.expand(sizes);

  auto dim = indptr.dim() - 1;
  CHECK_INPUT(src.size(dim) == 0 || src.size(dim) == indptr.size(dim) - 1);

  src = src.contiguous();

  torch::Tensor out;
  if (optional_out.has_value()) {
    out = optional_out.value().contiguous();
    for (auto i = 0; i < out.dim(); i++)
      if (i != dim)
        CHECK_INPUT(src.size(i) == out.size(i));
  } else {
    auto sizes = src.sizes().vec();
    if (src.numel() > 0) {
      sizes[dim] = indptr.flatten()[-1].cpu().data_ptr<int64_t>()[0];
    } else {
      sizes[dim] = 0;
    }
    out = torch::empty(sizes, src.options());
  }

  if (src.numel() == 0) {
    if (!optional_out.has_value())
      out.fill_(0);
    return out;
  }

  auto N = src.size(dim) * (indptr.numel() / indptr.size(-1));
  auto K = src.numel() / N;
  auto E = out.size(dim);

  auto indptr_info = at::cuda::detail::getTensorInfo<int64_t, int>(indptr);
  auto stream = at::cuda::getCurrentCUDAStream();
  AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, src.scalar_type(), "_", [&] {
    auto src_data = src.data_ptr<scalar_t>();
    auto out_data = out.data_ptr<scalar_t>();

    if (K == 1)
      gather_csr_kernel<scalar_t, 4><<<BLOCKS(1, 4 * N), THREADS, 0, stream>>>(
          src_data, indptr_info, out_data, N, E);
    else
      gather_csr_broadcast_kernel<scalar_t>
          <<<BLOCKS(1, N * K), THREADS, 0, stream>>>(src_data, indptr_info,
                                                     out_data, N, K, E);
  });

  return out;
}

// pcops - PointNet++ set-abstraction / feature-propagation operators.
//
//   ball_query         first `nsample` neighbours (in index order) within a radius
//   group_points       gather features of grouped neighbours (+ backward)
//   gather_points      gather features of sampled points (+ backward)
//   three_nn           three nearest known points of every unknown point
//   three_interpolate  inverse-distance interpolation from three neighbours (+ backward)
//
// Layouts follow PointNet++: xyz is [B, N, 3] (point-major), features are
// [B, C, N] (channel-major). All index tensors are int32. Distances are
// computed in the op-math type of the input (float for half/bfloat16).
#include "pointnet_cuda.h"

#include <ATen/OpMathType.h>
#include <ATen/cuda/Atomic.cuh>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

#define PN_THREADS 256

namespace pcops
{
namespace
{
inline int64_t pn_blocks(int64_t n) { return (n + PN_THREADS - 1) / PN_THREADS; }

// One thread per query point. Neighbours are taken in increasing point
// index; the first neighbour found fills every slot so that rows with fewer
// than nsample neighbours are padded with it. Queries without any neighbour
// keep index 0 (the output is zero-initialised).
template<typename scalar_t>
__global__ void ball_query_kernel(int64_t b, int64_t n, int64_t m, float radius2, int64_t nsample,
                                  const scalar_t *__restrict__ new_xyz, // [B, M, 3]
                                  const scalar_t *__restrict__ xyz,     // [B, N, 3]
                                  int32_t *__restrict__ idx)            // [B, M, S]
{
    using acc_t     = at::opmath_type<scalar_t>;
    const int64_t t = blockIdx.x * static_cast<int64_t>(blockDim.x) + threadIdx.x;
    if(t >= b * m)
    {
        return;
    }
    const int64_t bi = t / m;
    const scalar_t *q = new_xyz + t * 3;
    const scalar_t *p = xyz + bi * n * 3;
    int32_t *out      = idx + t * nsample;
    const acc_t qx = q[0], qy = q[1], qz = q[2];
    int64_t cnt    = 0;
    for(int64_t k = 0; k < n && cnt < nsample; ++k)
    {
        const acc_t dx = static_cast<acc_t>(p[k * 3 + 0]) - qx;
        const acc_t dy = static_cast<acc_t>(p[k * 3 + 1]) - qy;
        const acc_t dz = static_cast<acc_t>(p[k * 3 + 2]) - qz;
        const acc_t d2 = dx * dx + dy * dy + dz * dz;
        if(d2 < static_cast<acc_t>(radius2))
        {
            if(cnt == 0)
            {
                for(int64_t s = 0; s < nsample; ++s)
                {
                    out[s] = static_cast<int32_t>(k);
                }
            }
            out[cnt++] = static_cast<int32_t>(k);
        }
    }
}

template<typename scalar_t>
__global__ void group_points_kernel(int64_t b, int64_t c, int64_t n, int64_t m, int64_t s,
                                    const scalar_t *__restrict__ features, // [B, C, N]
                                    const int32_t *__restrict__ idx,       // [B, M, S]
                                    scalar_t *__restrict__ out)            // [B, C, M, S]
{
    const int64_t t = blockIdx.x * static_cast<int64_t>(blockDim.x) + threadIdx.x;
    if(t >= b * c * m * s)
    {
        return;
    }
    const int64_t si = t % s;
    const int64_t mi = (t / s) % m;
    const int64_t ci = (t / (s * m)) % c;
    const int64_t bi = t / (s * m * c);
    const int32_t k  = idx[(bi * m + mi) * s + si];
    out[t]           = features[(bi * c + ci) * n + k];
}

template<typename scalar_t>
__global__ void group_points_grad_kernel(int64_t b, int64_t c, int64_t n, int64_t m, int64_t s,
                                         const scalar_t *__restrict__ grad_out, // [B, C, M, S]
                                         const int32_t *__restrict__ idx,       // [B, M, S]
                                         scalar_t *__restrict__ grad_features)  // [B, C, N]
{
    const int64_t t = blockIdx.x * static_cast<int64_t>(blockDim.x) + threadIdx.x;
    if(t >= b * c * m * s)
    {
        return;
    }
    const int64_t si = t % s;
    const int64_t mi = (t / s) % m;
    const int64_t ci = (t / (s * m)) % c;
    const int64_t bi = t / (s * m * c);
    const int32_t k  = idx[(bi * m + mi) * s + si];
    gpuAtomicAdd(grad_features + (bi * c + ci) * n + k, grad_out[t]);
}

template<typename scalar_t>
__global__ void gather_points_kernel(int64_t b, int64_t c, int64_t n, int64_t m, const scalar_t *__restrict__ features,
                                     const int32_t *__restrict__ idx, scalar_t *__restrict__ out)
{
    const int64_t t = blockIdx.x * static_cast<int64_t>(blockDim.x) + threadIdx.x;
    if(t >= b * c * m)
    {
        return;
    }
    const int64_t mi = t % m;
    const int64_t bi = t / (m * c);
    const int64_t ci = (t / m) % c;
    out[t]           = features[(bi * c + ci) * n + idx[bi * m + mi]];
}

template<typename scalar_t>
__global__ void gather_points_grad_kernel(int64_t b, int64_t c, int64_t n, int64_t m, const scalar_t *__restrict__ grad_out,
                                          const int32_t *__restrict__ idx, scalar_t *__restrict__ grad_features)
{
    const int64_t t = blockIdx.x * static_cast<int64_t>(blockDim.x) + threadIdx.x;
    if(t >= b * c * m)
    {
        return;
    }
    const int64_t mi = t % m;
    const int64_t bi = t / (m * c);
    const int64_t ci = (t / m) % c;
    gpuAtomicAdd(grad_features + (bi * c + ci) * n + idx[bi * m + mi], grad_out[t]);
}

// One thread per unknown point. Strict comparisons keep the earliest index on
// ties. With fewer than three known points the unused slots keep index 0 and
// distance 1e40 (+inf once stored in a float tensor).
template<typename scalar_t>
__global__ void three_nn_kernel(int64_t b, int64_t n, int64_t m,
                                const scalar_t *__restrict__ unknown, // [B, n, 3]
                                const scalar_t *__restrict__ known,   // [B, m, 3]
                                scalar_t *__restrict__ dist2,         // [B, n, 3]
                                int32_t *__restrict__ idx)            // [B, n, 3]
{
    using acc_t     = at::opmath_type<scalar_t>;
    const int64_t t = blockIdx.x * static_cast<int64_t>(blockDim.x) + threadIdx.x;
    if(t >= b * n)
    {
        return;
    }
    const int64_t bi  = t / n;
    const scalar_t *u = unknown + t * 3;
    const scalar_t *k = known + bi * m * 3;
    const acc_t ux = u[0], uy = u[1], uz = u[2];
    double best1 = 1e40, best2 = 1e40, best3 = 1e40;
    int32_t besti1 = 0, besti2 = 0, besti3 = 0;
    for(int64_t j = 0; j < m; ++j)
    {
        const acc_t dx = static_cast<acc_t>(k[j * 3 + 0]) - ux;
        const acc_t dy = static_cast<acc_t>(k[j * 3 + 1]) - uy;
        const acc_t dz = static_cast<acc_t>(k[j * 3 + 2]) - uz;
        const acc_t d  = dx * dx + dy * dy + dz * dz;
        if(d < best1)
        {
            best3  = best2;
            besti3 = besti2;
            best2  = best1;
            besti2 = besti1;
            best1  = d;
            besti1 = static_cast<int32_t>(j);
        }
        else if(d < best2)
        {
            best3  = best2;
            besti3 = besti2;
            best2  = d;
            besti2 = static_cast<int32_t>(j);
        }
        else if(d < best3)
        {
            best3  = d;
            besti3 = static_cast<int32_t>(j);
        }
    }
    dist2[t * 3 + 0] = static_cast<scalar_t>(best1);
    dist2[t * 3 + 1] = static_cast<scalar_t>(best2);
    dist2[t * 3 + 2] = static_cast<scalar_t>(best3);
    idx[t * 3 + 0]   = besti1;
    idx[t * 3 + 1]   = besti2;
    idx[t * 3 + 2]   = besti3;
}

template<typename scalar_t>
__global__ void three_interpolate_kernel(int64_t b, int64_t c, int64_t m, int64_t n,
                                         const scalar_t *__restrict__ features, // [B, C, m]
                                         const int32_t *__restrict__ idx,       // [B, n, 3]
                                         const scalar_t *__restrict__ weight,   // [B, n, 3]
                                         scalar_t *__restrict__ out)            // [B, C, n]
{
    using acc_t     = at::opmath_type<scalar_t>;
    const int64_t t = blockIdx.x * static_cast<int64_t>(blockDim.x) + threadIdx.x;
    if(t >= b * c * n)
    {
        return;
    }
    const int64_t ni  = t % n;
    const int64_t ci  = (t / n) % c;
    const int64_t bi  = t / (n * c);
    const int64_t w   = (bi * n + ni) * 3;
    const scalar_t *f = features + (bi * c + ci) * m;
    const acc_t v     = static_cast<acc_t>(weight[w + 0]) * static_cast<acc_t>(f[idx[w + 0]])
                  + static_cast<acc_t>(weight[w + 1]) * static_cast<acc_t>(f[idx[w + 1]])
                  + static_cast<acc_t>(weight[w + 2]) * static_cast<acc_t>(f[idx[w + 2]]);
    out[t] = static_cast<scalar_t>(v);
}

template<typename scalar_t>
__global__ void three_interpolate_grad_kernel(int64_t b, int64_t c, int64_t n, int64_t m,
                                              const scalar_t *__restrict__ grad_out, // [B, C, n]
                                              const int32_t *__restrict__ idx,       // [B, n, 3]
                                              const scalar_t *__restrict__ weight,   // [B, n, 3]
                                              scalar_t *__restrict__ grad_features)  // [B, C, m]
{
    using acc_t     = at::opmath_type<scalar_t>;
    const int64_t t = blockIdx.x * static_cast<int64_t>(blockDim.x) + threadIdx.x;
    if(t >= b * c * n)
    {
        return;
    }
    const int64_t ni = t % n;
    const int64_t ci = (t / n) % c;
    const int64_t bi = t / (n * c);
    const int64_t w  = (bi * n + ni) * 3;
    const acc_t g    = grad_out[t];
    scalar_t *gf     = grad_features + (bi * c + ci) * m;
    for(int j = 0; j < 3; ++j)
    {
        gpuAtomicAdd(gf + idx[w + j], static_cast<scalar_t>(g * static_cast<acc_t>(weight[w + j])));
    }
}

void check_xyz(const torch::Tensor &t, const char *name)
{
    TORCH_CHECK(t.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(t.dim() == 3 && t.size(2) == 3, name, " must have shape [B, N, 3], got ", t.sizes());
}

void check_idx(const torch::Tensor &t, const char *name)
{
    TORCH_CHECK(t.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(t.scalar_type() == torch::kInt, name, " must be int32");
}
} // namespace

#define PCOPS_DISPATCH(TYPE, NAME, ...) \
    AT_DISPATCH_FLOATING_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, TYPE, NAME, __VA_ARGS__)

torch::Tensor ball_query_cuda(torch::Tensor new_xyz, torch::Tensor xyz, double radius, int64_t nsample)
{
    check_xyz(new_xyz, "new_xyz");
    check_xyz(xyz, "xyz");
    TORCH_CHECK(new_xyz.size(0) == xyz.size(0), "batch sizes differ");
    TORCH_CHECK(new_xyz.scalar_type() == xyz.scalar_type(), "new_xyz and xyz must have the same dtype");
    TORCH_CHECK(nsample > 0, "nsample must be positive");
    c10::cuda::CUDAGuard guard(xyz.device());
    new_xyz       = new_xyz.contiguous();
    xyz           = xyz.contiguous();
    const auto b  = xyz.size(0), n = xyz.size(1), m = new_xyz.size(1);
    auto idx      = torch::zeros({b, m, nsample}, xyz.options().dtype(torch::kInt));
    if(b * m == 0)
    {
        return idx;
    }
    auto stream = at::cuda::getCurrentCUDAStream();
    PCOPS_DISPATCH(xyz.scalar_type(), "ball_query", [&] {
        ball_query_kernel<scalar_t><<<pn_blocks(b * m), PN_THREADS, 0, stream>>>(
            b, n, m, static_cast<float>(radius * radius), nsample, new_xyz.data_ptr<scalar_t>(), xyz.data_ptr<scalar_t>(),
            idx.data_ptr<int32_t>());
    });
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return idx;
}

torch::Tensor group_points_cuda(torch::Tensor features, torch::Tensor idx)
{
    TORCH_CHECK(features.is_cuda() && features.dim() == 3, "features must be a [B, C, N] CUDA tensor");
    check_idx(idx, "idx");
