# Deterministic transpose of an index list.  Sorting (index, original-position)
# fixes the accumulation order independently of CTA scheduling.
@triton.jit
def index_count_kernel(idx,counts,B:tl.constexpr,L:tl.constexpr,N:tl.constexpr,
                       I0:tl.constexpr,I1:tl.constexpr,I2:tl.constexpr,S:tl.constexpr,BLOCK:tl.constexpr):
    p=tl.program_id(0)*BLOCK+tl.arange(0,BLOCK);mask=p<B*L;b=p//L;q=p%L
    if S > 1: ix=tl.load(idx+b*I0+(q//S)*I1+(q%S)*I2,mask=mask,other=0)
    else: ix=tl.load(idx+b*I0+q*I1,mask=mask,other=0)
    tl.atomic_add(counts+b*N+ix,1,mask=mask)

@triton.jit
def index_prefix_kernel(counts,offsets,maxout,B:tl.constexpr,N:tl.constexpr,BLOCK:tl.constexpr):
    b=tl.program_id(0);j=tl.arange(0,BLOCK);v=tl.load(counts+b*N+j,mask=j<N,other=0);p=tl.cumsum(v,axis=0)-v
    tl.store(offsets+b*(N+1)+j,p,mask=j<N);tl.store(offsets+b*(N+1)+N,tl.sum(v,axis=0))
    tl.atomic_max(maxout,tl.max(v,axis=0))

@triton.jit
def index_sort_kernel(idx,perm,B:tl.constexpr,L:tl.constexpr,
                      I0:tl.constexpr,I1:tl.constexpr,I2:tl.constexpr,S:tl.constexpr,BLOCK:tl.constexpr):
    b=tl.program_id(0);p=tl.arange(0,BLOCK);mask=p<L
    if S > 1: ix=tl.load(idx+b*I0+(p//S)*I1+(p%S)*I2,mask=mask,other=0).to(tl.int64)
    else: ix=tl.load(idx+b*I0+p*I1,mask=mask,other=0).to(tl.int64)
    key=tl.where(mask,ix*(L+1)+p,0x7fffffffffffffff);key=tl.sort(key,dim=0)
